30	type FxDashMap<K, V> = DashMap<K, V, FxBuildHasher>;
31	type FxDashSet<K> = DashSet<K, FxBuildHasher>;
32	/// The files that augment React which the module a `(scope, specifier)` resolved to leads to, parsed, once the first
33	/// demand of the scope has searched them; [`ReadFailed`] when the search could not read a file, for every demand of the
34	/// scope.
35	type ModuleCell = Arc<OnceLock<Result<Vec<(Utf8PathBuf, Arc<SourceData>)>, ReadFailed>>>;
36	
37	/// A file's data, read and parsed once per load whoever asks first, a failed read included (`Loader::parse_source`).
38	type ParseCell = Arc<OnceLock<Result<Option<Arc<SourceData>>, ReadFailed>>>;
39	
40	/// Whether a file merges declarations into React, and the specifiers it re-exports, in order.
41	type Scan = (bool, Arc<[String]>);
42	
43	/// A [`Scan`] of a file, read once per load (`Loader::augmentation_scan`).
44	type ScanCell = Arc<OnceLock<Result<Option<Scan>, ReadFailed>>>;
45	
46	/// A dependency file that exists but could not be read (a permission, too many open files, an install racing the run):
47	/// what it declares is unknown, not absent. Every consumer of `Loader::read` and `Loader::parse` gets it and passes it
48	/// on: an answer derived from it is used by this load only, never kept in the layer or the index, and the demand that
49	/// met it is not recorded as followed, so the next load over the layer follows it again.
50	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
51	struct ReadFailed;
52	
53	/// What one probe of a directory found, once it has run (`probe_once`).
54	type ProbeCell = Arc<OnceLock<bool>>;
55	
56	/// `(directory of the importing file, specifier, exported name path)`.
57	type DemandKey = (Box<str>, Box<str>, CompactString);
58	
59	/// A name a file uses from another module: `specifier` as written in `from`, and the exported name path
60	/// (`Accordion.Root` for `RadixPrimitive.Accordion.Root` through `import * as RadixPrimitive`).
61	#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
62	pub(crate) struct Demand {
63	    pub(crate) from: Utf8PathBuf,
64	    pub(crate) specifier: Box<str>,
65	    pub(crate) name: CompactString,
66	}
67	
68	impl Demand {
69	    fn key(&self) -> DemandKey {
70	        let dir = self.from.parent().map_or("", Utf8Path::as_str);
71	        (Box::from(dir), self.specifier.clone(), self.name.clone())
72	    }
73	}
74	
75	/// Why a demand found no declaration.
76	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
77	pub(crate) enum Unresolved {
78	    /// The specifier resolves to nothing.
79	    Unresolvable,
80	    /// The module resolves, but to JavaScript with no declaration file.
81	    NoTypes,
82	    /// The module has types, but none of its exports is the name.
83	    NotExported,
84	}
85	
86	impl Unresolved {
87	    pub(crate) fn describe(self) -> &'static str {
88	        match self {
89	            Unresolved::Unresolvable => "its module could not be resolved",
90	            Unresolved::NoTypes => "its package ships no type declarations",
91	            Unresolved::NotExported => "its package's types do not export it",
92	        }
93	    }
94	}
