104	// ─── Demands ──────────────────────────────────────────────────────────────────
105	
106	/// Every name `data` uses in a type: references, `typeof` queries, heritage and type arguments, in its interfaces,
107	/// type aliases and component props.
108	fn referenced_names(data: &SourceData, out: &mut FxHashSet<CompactString>) {
109	    for iface in data.interfaces.values() {
110	        interface_refs(iface, out);
111	    }
112	    for alias in data.type_aliases.values() {
113	        alias_refs(alias, out);
114	    }
115	    for mapping in &data.component_mappings {
116	        mapping_refs(mapping, out);
117	    }
118	}
119	
120	fn interface_refs(iface: &CollectedInterface, out: &mut FxHashSet<CompactString>) {
121	    for prop in &iface.props {
122	        type_refs(&prop.collected_type, out);
123	    }
124	    for extends in &iface.extends {
125	        let (name, args) = match extends {
126	            ExtendsRef::SameFile { name, type_args } => (name, type_args),
127	            ExtendsRef::Imported { local_name, type_args, .. } => (local_name, type_args),
128	            ExtendsRef::Builtin { name, type_args, .. } => (name, type_args),
129	        };
130	        out.insert(CompactString::from(name.as_str()));
131	        args.iter().for_each(|arg| type_refs(arg, out));
132	    }
133	}
134	
135	fn alias_refs(alias: &CollectedTypeAlias, out: &mut FxHashSet<CompactString>) {
136	    match alias {
137	        CollectedTypeAlias::Omit { base, keys, .. } | CollectedTypeAlias::Pick { base, keys, .. } => {
138	            type_refs(base, out);
139	            type_refs(keys, out);
140	        }
141	        CollectedTypeAlias::Partial { base, .. } | CollectedTypeAlias::Required { base, .. } => type_refs(base, out),
142	        CollectedTypeAlias::Union { members, .. } | CollectedTypeAlias::Intersection { members, .. } => {
143	            members.iter().for_each(|member| type_refs(member, out));
144	        }
145	        CollectedTypeAlias::Passthrough { target, .. } => type_refs(target, out),
146	        CollectedTypeAlias::LiteralUnion { .. } => {}
147	    }
148	}
149	
150	fn mapping_refs(mapping: &ComponentMapping, out: &mut FxHashSet<CompactString>) {
151	    out.insert(CompactString::from(mapping.props_type_name.as_str()));
152	    mapping.props_type_args.iter().for_each(|arg| type_refs(arg, out));
153	    // A factory call's callback annotation (`make('div', (props: ExternalProps) => ...)`) names types only here.
154	    if let Some(factory_props) = &mapping.factory_props {
155	        type_refs(factory_props, out);
156	    }
157	}
158	
159	fn type_refs(ty: &CollectedType, out: &mut FxHashSet<CompactString>) {
160	    match ty {
161	        CollectedType::Named { name, args } => {
162	            out.insert(name.clone());
163	            args.iter().for_each(|arg| type_refs(arg, out));
164	        }
165	        CollectedType::TypeOf(name) => {
166	            out.insert(name.clone());
167	        }
168	        CollectedType::Union(members)
169	        | CollectedType::Intersection(members)
170	        | CollectedType::TemplateLiteral(members) => members.iter().for_each(|member| type_refs(member, out)),
171	        CollectedType::Tuple(elements) => elements.iter().for_each(|element| type_refs(&element.element_type, out)),
172	        CollectedType::Array(inner) | CollectedType::Readonly(inner) | CollectedType::KeyOf(inner) => {
173	            type_refs(inner, out)
174	        }
175	        CollectedType::AtFile { inner, .. } => type_refs(inner, out),
176	        CollectedType::Object(fields) => field_refs(fields, out),
177	        CollectedType::Callable { signatures, fields } => {
178	            for signature in signatures {
179	                let mut inner = FxHashSet::default();
180	                signature.params.iter().for_each(|param| type_refs(param, &mut inner));
181	                type_refs(&signature.return_type, &mut inner);
182	                out.extend(inner.into_iter().filter(|name| !signature.type_params.contains(name)));
183	            }
184	            field_refs(fields, out);
185	        }
186	        CollectedType::IndexedAccess { obj, key } => {
187	            type_refs(obj, out);
188	            type_refs(key, out);
189	        }
190	        CollectedType::Function { type_params, params, return_type, .. } => {
191	            let mut inner = FxHashSet::default();
192	            params.iter().for_each(|param| type_refs(param, &mut inner));
193	            type_refs(return_type, &mut inner);
194	            out.extend(inner.into_iter().filter(|name| !type_params.contains(name)));
195	        }
196	        CollectedType::Conditional { check, extends_type, true_type, false_type } => {
197	            for part in [check, extends_type, true_type, false_type] {
198	                type_refs(part, out);
199	            }
200	        }
201	        CollectedType::Mapped { param, key_type, value_type, .. } => {
202	            type_refs(key_type, out);
203	            let mut inner = FxHashSet::default();
204	            type_refs(value_type, &mut inner);
205	            out.extend(inner.into_iter().filter(|name| name != param));
206	        }
207	        CollectedType::String
208	        | CollectedType::Number
209	        | CollectedType::Boolean
210	        | CollectedType::Null
211	        | CollectedType::Undefined
212	        | CollectedType::Any
213	        | CollectedType::Never
214	        | CollectedType::Unknown
215	        | CollectedType::Void
216	        | CollectedType::BigInt
217	        | CollectedType::Symbol
218	        | CollectedType::StringLiteral(_)
219	        | CollectedType::NumberLiteral(_)
220	        | CollectedType::BoolLiteral(_)
221	        | CollectedType::BigIntLiteral(_)
222	        | CollectedType::UniqueSymbol
223	        | CollectedType::Raw(_) => {}
224	    }
225	}
226	
227	fn field_refs(fields: &[crate::types::CollectedObjectField], out: &mut FxHashSet<CompactString>) {
228	    fields.iter().for_each(|field| {
229	        type_refs(&field.collected_type, out);
230	        if let Some(key) = &field.index_key {
231	            type_refs(key, out);
232	        }
233	    })
234	}
