236	/// The module and exported name path `reference` (as written in `file`) reaches through one of `imports`, if it is
237	/// imported.
238	fn imported_demand(file: &Utf8Path, imports: &[ImportBinding], reference: &str) -> Option<Demand> {
239	    let (head, rest) = match reference.split_once('.') {
240	        Some((head, rest)) => (head, Some(rest)),
241	        None => (reference, None),
242	    };
243	    let Some(binding) = imports.iter().find(|binding| binding.local_name == head) else {
244	        // `@types/react`'s UMD global (`export as namespace React`): `React.CSSProperties` without an import.
245	        let name = rest.filter(|_| head == "React")?;
246	        return Some(Demand { from: file.to_owned(), specifier: Box::from("react"), name: CompactString::from(name) });
247	    };
248	    let name = match (binding.exported_name.as_str(), rest) {
249	        ("*", Some(rest)) => CompactString::from(rest),
250	        ("*", None) => return None,
251	        (exported, Some(rest)) => CompactString::from(format!("{exported}.{rest}")),
252	        (exported, None) => CompactString::from(exported),
253	    };
254	    Some(Demand { from: file.to_owned(), specifier: Box::from(binding.specifier.as_str()), name })
255	}
256	
257	/// What project file `file` takes from packages (bare specifiers), sorted: each name it imports and uses in a type, and
258	/// each module it imports at all (a [`Demand`] with an empty name). TypeScript reads a module's React augmentations
259	/// whenever the program reaches the module, whether or not the file uses a name from it.
260	pub(crate) fn project_demands(file: &Utf8Path, data: &SourceData) -> Vec<Demand> {
261	    let mut refs = FxHashSet::default();
262	    referenced_names(data, &mut refs);
263	    let bare = |specifier: &str| !specifier.starts_with('.') && !specifier.starts_with('/');
264	    let mut demands: Vec<Demand> = refs
265	        .iter()
266	        .filter_map(|reference| imported_demand(file, &data.imports, reference))
267	        .filter(|demand| bare(&demand.specifier))
268	        .collect();
269	    demands.extend(data.imports.iter().filter(|binding| bare(&binding.specifier)).map(|binding| Demand {
270	        from: file.to_owned(),
271	        specifier: Box::from(binding.specifier.as_str()),
272	        name: CompactString::default(),
273	    }));
274	    // Every demand is from `file`, so the derived order's first key, a path of a hundred bytes, only ever ties.
275	    demands.sort_unstable_by(|a, b| (&a.specifier, &a.name).cmp(&(&b.specifier, &b.name)));
276	    demands.dedup();
277	    demands
278	}
279	
280	// ─── The layer ────────────────────────────────────────────────────────────────
281	
282	/// How many files, the module included, a search for React augmentations reads through one module's re-exports.
283	const AUGMENTATION_SCAN_FILES: usize = 64;
284	
285	/// How many layers a chain holds before the next extension flattens it into one.
286	///
287	/// An extension adds only the files it loaded, as a layer over the one it extends, so a growth costs what it loads and
288	/// not what the session already holds. Lookups walk the chain, so it is kept short: a flatten copies everything once
289	/// and the chain starts again.
290	const MAX_CHAIN_DEPTH: usize = 8;
291	
292	/// The sizes of a layer and its parents together, for [`DependencyLayer::resolves_like`] and `file_count`.
293	#[derive(Clone, Copy, Default)]
294	struct Totals {
295	    files: usize,
296	    react_files: usize,
297	    exports: usize,
298	    resolutions: usize,
299	    unresolved: usize,
300	}
301	
302	/// The dependency declarations a run loaded. Immutable once built; a watch revision or a lazy session that needs more
303	/// builds a new one over it, holding only what the extension added.
304	pub(crate) struct DependencyLayer {
305	    /// The layer this one extends. Everything below is this layer's own additions; the parent's are consulted through
306	    /// the accessors, `named_types` and `import_map`.
307	    parent: Option<Arc<DependencyLayer>>,
308	    /// Layers below this one.
309	    depth: usize,
310	    totals: Totals,
311	    /// Declaring files' component mappings: the value index. Nothing here is emitted.
312	    component_mappings: Vec<ComponentMapping>,
313	    /// Positions in `component_mappings` by component name, ascending: `ComponentProps<typeof X>` asks `component` for a
314	    /// name that is usually not here, and comparing every mapping's path to find that out dominated a design system's run.
315	    component_positions: FxHashMap<CompactString, Vec<usize>>,
316	    /// Falls back to the parent's.
317	    pub(crate) named_types: Arc<NamedTypeIndex>,
318	    /// Falls back to the parent's.
319	    pub(crate) import_map: Arc<ImportResolutionMap>,
320	    /// `(module, name)` → the declaring `(file, name)`, or `None` when the module's types do not export it.
321	    exports: dashmap::ReadOnlyView<(PathKey, CompactString), Option<(Utf8PathBuf, CompactString)>, FxBuildHasher>,
322	    /// `(directory, specifier)` → module, for every resolution the loader made.
323	    resolutions: FxHashMap<(Box<str>, Box<str>), Result<Utf8PathBuf, Unresolved>>,
324	    files: FxHashSet<PathKey>,
325	    /// React's files whose declarations' imports were followed; their imports are in `import_map`.
326	    react_files: FxHashSet<PathKey>,
327	    /// Each module a demand reached, with the files its re-exports lead to that augment React.
328	    augmenters: FxHashMap<PathKey, Vec<Utf8PathBuf>>,
329	    demands: FxHashSet<DemandKey>,
330	    unresolved: FxHashMap<DemandKey, Unresolved>,
331	    /// The `(file, name)` declarations whose references were followed.
332	    claimed: FxHashSet<(PathKey, CompactString)>,
333	    /// Every parsed file's data (stubs included), so an extension reuses them.
334	    parsed: FxHashMap<PathKey, Option<Arc<SourceData>>>,
335	    /// The panics this layer's own demands hit, contained, and the dependency files it could not read; the demands they
336	    /// covered stay unanswered.
337	    panics: Vec<Diagnostic>,
338	    /// A dependency file could not be read while this layer, or one it extends, was loaded ([`ReadFailed`]). The layer
339	    /// holds nothing derived from it, but what it holds is not the whole answer, so no load over it writes the index.
340	    degraded: bool,
341	}
342	
343	impl DependencyLayer {
344	    /// The contained panics of this layer and the ones it extends, in message order.
345	    pub(crate) fn panic_diagnostics(&self) -> Vec<Diagnostic> {
346	        let mut all: Vec<Diagnostic> = self.chain().flat_map(|layer| layer.panics.iter().cloned()).collect();
347	        all.sort_by(|a, b| a.message.cmp(&b.message));
348	        all
349	    }
350	
351	    /// This layer and then each one it extends.
352	    fn chain(&self) -> impl Iterator<Item = &DependencyLayer> {
353	        std::iter::successors(Some(self), |layer| layer.parent.as_deref())
354	    }
355	
356	    /// How many declaration files this layer holds, with its parents'.
357	    pub(crate) fn file_count(&self) -> usize {
358	        self.totals.files
359	    }
360	
361	    pub(crate) fn is_dependency_file(&self, file: &Utf8Path) -> bool {
362	        self.chain().any(|layer| layer.files.contains(file.as_str()))
363	    }
364	
365	    /// The declaring `(file, name)` of `name` exported from `module`, when the loader answered it.
366	    pub(crate) fn export_of(&self, module: &Utf8Path, name: &str) -> Option<&Option<(Utf8PathBuf, CompactString)>> {
367	        self.export_entry(&(PathKey::from(module), CompactString::from(name)))
368	    }
369	
370	    fn export_entry(&self, key: &(PathKey, CompactString)) -> Option<&Option<(Utf8PathBuf, CompactString)>> {
371	        self.chain().find_map(|layer| layer.exports.get(key))
372	    }
373	
374	    fn resolution(&self, key: &(Box<str>, Box<str>)) -> Option<&Result<Utf8PathBuf, Unresolved>> {
375	        self.chain().find_map(|layer| layer.resolutions.get(key))
376	    }
377	
378	    fn parsed_data(&self, file: &str) -> Option<&Option<Arc<SourceData>>> {
379	        self.chain().find_map(|layer| layer.parsed.get(file))
380	    }
381	
382	    fn augmenters_of(&self, module: &PathKey) -> Option<&Vec<Utf8PathBuf>> {
383	        self.chain().find_map(|layer| layer.augmenters.get(module))
384	    }
385	
386	    fn has_react_file(&self, file: &str) -> bool {
387	        self.chain().any(|layer| layer.react_files.contains(file))
388	    }
389	
390	    fn has_demand(&self, key: &DemandKey) -> bool {
391	        self.chain().any(|layer| layer.demands.contains(key))
392	    }
393	
394	    fn has_claimed(&self, key: &(PathKey, CompactString)) -> bool {
395	        self.chain().any(|layer| layer.claimed.contains(key))
396	    }
397	
398	    /// A dependency component by its declaring `(file, name)`.
399	    pub(crate) fn component(&self, file: &Utf8Path, name: &str) -> Option<&ComponentMapping> {
400	        self.chain().find_map(|layer| {
401	            layer
402	                .component_positions
403	                .get(name)?
404	                .iter()
405	                .filter_map(|&position| layer.component_mappings.get(position))
406	                .find(|mapping| mapping.file_path == file)
407	        })
408	    }
409	
410	    /// Why the loader found no declaration for `name` imported from `specifier` by a file in `dir`, if it didn't.
411	    pub(crate) fn unresolved_reason(&self, dir: &Utf8Path, specifier: &str, name: &str) -> Option<Unresolved> {
412	        let key = (Box::from(dir.as_str()), Box::from(specifier), CompactString::from(name));
413	        self.chain().find_map(|layer| layer.unresolved.get(&key)).copied()
414	    }
415	
416	    /// Whether `other`, a layer this one was extended from, resolves every name the way this one does: extending only
417	    /// adds, so equal counts mean nothing was added.
418	    pub(crate) fn resolves_like(&self, other: &DependencyLayer) -> bool {
419	        let (a, b) = (self.totals, other.totals);
420	        a.files == b.files
421	            && a.react_files == b.react_files
422	            && a.exports == b.exports
423	            && a.resolutions == b.resolutions
424	            && a.unresolved == b.unresolved
425	    }
426	
427	    /// Whether this layer has followed every one of `demands`.
428	    pub(crate) fn covers(&self, demands: &[Demand]) -> bool {
429	        demands.iter().all(|d| self.has_demand(&d.key()))
430	    }
431	
432	    /// The demands of `demands` this layer has not followed.
433	    pub(crate) fn missing(&self, demands: &[Demand]) -> Vec<Demand> {
434	        demands.iter().filter(|d| !self.has_demand(&d.key())).cloned().collect()
435	    }
436	}
