438	// ─── Loading ──────────────────────────────────────────────────────────────────
439	
440	struct Loader<'a> {
441	    resolvers: &'a ModuleResolvers,
442	    project_dirs: &'a [Utf8PathBuf],
443	    /// The layer being extended, consulted before the maps below so an extension holds only its own additions.
444	    parent: Option<&'a DependencyLayer>,
445	    parsed: FxDashMap<PathKey, ParseCell>,
446	    resolutions: FxDashMap<(Box<str>, Box<str>), Result<Utf8PathBuf, Unresolved>>,
447	    exports: FxDashMap<(PathKey, CompactString), Option<(Utf8PathBuf, CompactString)>>,
448	    claimed: FxDashSet<(PathKey, CompactString)>,
449	    declaring: FxDashSet<PathKey>,
450	    react_files: FxDashSet<PathKey>,
451	    augmenters: FxDashMap<PathKey, Vec<Utf8PathBuf>>,
452	    /// For each module in `augmenters`, the stamps of the other packages its search read files from.
453	    augmenter_crossed: FxDashMap<PathKey, Vec<PackageStampRow>>,
454	    demands: FxDashSet<DemandKey>,
455	    /// The demands of `demands` that met a file that could not be read: not followed, as far as the layer says.
456	    failed: FxDashSet<DemandKey>,
457	    unresolved: FxDashMap<DemandKey, Unresolved>,
458	    /// Whether each directory `package_of` passed has a `package.json` file.
459	    package_manifests: FxDashMap<Box<str>, ProbeCell>,
460	    /// What `package_of` answered for each directory it was asked about, so a repeat is one lookup, not a walk.
461	    packages: FxDashMap<Box<str>, Option<Box<str>>>,
462	    /// Whether each directory `resolution_scope` passed has one of its marks.
463	    scope_marks: FxDashMap<Box<str>, ProbeCell>,
464	    /// What `resolution_scope` answered for each directory it was asked about.
465	    scopes: FxDashMap<Box<str>, Box<str>>,
466	    /// What each `(scope, specifier)` of a module-only demand resolved to, when outside the project and not React's.
467	    module_demands: FxDashMap<(Box<str>, Box<str>), ModuleCell>,
468	    /// What an augmentation search found in each file it passed through that was not parsed already.
469	    scans: FxDashMap<PathKey, ScanCell>,
470	    /// Something was resolved or answered that the index did not hold.
471	    learned: AtomicBool,
472	    /// The diagnostics of demands that panicked and of dependency files that could not be read.
473	    panics: Mutex<Vec<Diagnostic>>,
474	    /// A dependency file existed but could not be read ([`ReadFailed`]).
475	    read_failed: AtomicBool,
476	    /// How many times each file was read, and how long each read waits first, so a test can make readers meet.
477	    #[cfg(test)]
478	    reads: FxDashMap<PathKey, usize>,
479	    #[cfg(test)]
480	    read_pause: std::time::Duration,
481	}
482	
483	impl<'a> Loader<'a> {
484	    fn new(
485	        resolvers: &'a ModuleResolvers,
486	        project_dirs: &'a [Utf8PathBuf],
487	        parent: Option<&'a DependencyLayer>,
488	    ) -> Self {
489	        Loader {
490	            resolvers,
491	            project_dirs,
492	            parent,
493	            parsed: DashMap::default(),
494	            resolutions: DashMap::default(),
495	            exports: DashMap::default(),
496	            claimed: DashSet::default(),
497	            declaring: DashSet::default(),
498	            react_files: DashSet::default(),
499	            augmenters: DashMap::default(),
500	            augmenter_crossed: DashMap::default(),
501	            demands: DashSet::default(),
502	            failed: DashSet::default(),
503	            unresolved: DashMap::default(),
504	            package_manifests: DashMap::default(),
505	            packages: DashMap::default(),
506	            scope_marks: DashMap::default(),
507	            scopes: DashMap::default(),
508	            module_demands: DashMap::default(),
509	            scans: DashMap::default(),
510	            learned: AtomicBool::new(false),
511	            panics: Mutex::new(Vec::new()),
512	            read_failed: AtomicBool::new(false),
513	            #[cfg(test)]
514	            reads: DashMap::default(),
515	            #[cfg(test)]
516	            read_pause: std::time::Duration::ZERO,
517	        }
518	    }
519	}
520	
521	impl Loader<'_> {
522	    /// The text of a dependency file. One that is missing is skipped quietly (`Ok(None)`), since resolution found it a
523	    /// moment ago and a dangling link or a racing uninstall declares nothing. One that exists but cannot be read is
524	    /// [`ReadFailed`], reported once.
525	    fn read(&self, file: &Utf8Path) -> Result<Option<String>, ReadFailed> {
