621	    /// `find_export` within one walk. A lookup that met a module already on the walk (a re-export cycle) is `cut`: its
622	    /// answer depends on where the walk entered the cycle, so it is returned but not kept, and the cut propagates to
623	    /// every lookup that relied on it. Kept answers are therefore the same in any order and on any thread. A walk that
624	    /// could not read a module on its way has no answer: [`ReadFailed`], and nothing on the walk is kept.
625	    fn find_export_in(
626	        &self,
627	        module: &Utf8Path,
628	        name: &str,
629	        visited: &mut FxHashSet<(PathKey, CompactString)>,
630	        cut: &mut bool,
631	    ) -> Result<Option<(Utf8PathBuf, CompactString)>, ReadFailed> {
632	        let key = (PathKey::from(module), CompactString::from(name));
633	        if let Some(found) = self.exports.get(&key) {
634	            return Ok(found.clone());
635	        }
636	        if let Some(found) = self.parent.and_then(|parent| parent.export_entry(&key)) {
637	            return Ok(found.clone());
638	        }
639	        if !visited.insert(key.clone()) {
640	            *cut = true;
641	            return Ok(None);
642	        }
643	        let mut own_cut = false;
644	        let found = self.find_export_uncached(module, name, visited, &mut own_cut);
645	        visited.remove(&key);
646	        let found = found?;
647	        if own_cut {
648	            *cut = true;
649	        } else {
650	            if let Some(dir) = module.parent() {
651	                self.learn(dir);
652	            }
653	            self.exports.insert(key, found.clone());
654	        }
655	        Ok(found)
656	    }
