658	    fn find_export_uncached(
659	        &self,
660	        module: &Utf8Path,
661	        name: &str,
662	        visited: &mut FxHashSet<(PathKey, CompactString)>,
663	        cut: &mut bool,
664	    ) -> Result<Option<(Utf8PathBuf, CompactString)>, ReadFailed> {
665	        let Some(data) = self.parse(module)? else { return Ok(None) };
666	        if declares(&data, module, name) {
667	            return Ok(Some((module.to_owned(), CompactString::from(name))));
668	        }
669	        // A member of a value the module declares (`Primitive.div`): its declaration is the value's.
670	        if name.split_once('.').is_some_and(|(head, _)| declares(&data, module, head)) {
671	            return Ok(Some((module.to_owned(), CompactString::from(name))));
672	        }
673	        let (head, rest) = match name.split_once('.') {
674	            Some((head, rest)) => (head, Some(rest)),
675	            None => (name, None),
676	        };
677	        for export in &data.exports {
678	            match export {
679	                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } if local_name == head => {
680	                    // An explicit export shadows a wildcard one, so a hop that cannot be resolved leaves the name unanswered
681	                    // rather than to a later `export *`; `unresolved_cause` names the hop.
682	                    let Ok(target) = self.resolve(module, source_specifier) else { return Ok(None) };
683	                    let next = match rest {
684	                        Some(rest) => format!("{source_name}.{rest}"),
685	                        None => source_name.clone(),
686	                    };
687	                    return self.find_export_in(&target, &next, visited, cut);
688	                }
689	                LexedExport::ReExportNamespace { namespace, source_specifier } if namespace == head => {
690	                    let (Ok(target), Some(rest)) = (self.resolve(module, source_specifier), rest) else {
691	                        return Ok(None);
692	                    };
693	                    return self.find_export_in(&target, rest, visited, cut);
694	                }
695	                // `export { DialogContent as Content }`, the way bundled typings (Radix's) name their parts.
696	                LexedExport::LocalDeclaration { name: exported, declared_as: Some(local), .. }
697	                    if exported == head && declares(&data, module, local) =>
698	                {
699	                    let name = match rest {
700	                        Some(rest) => format!("{local}.{rest}"),
701	                        None => local.clone(),
702	                    };
703	                    return Ok(Some((module.to_owned(), CompactString::from(name))));
704	                }
705	                _ => {}
706	            }
707	        }
708	        // A local export can name an imported binding (`import Image from './Image'; export default Image`).
709	        if let Some(local) = data.exports.iter().find_map(|export| match export {
710	            LexedExport::LocalDeclaration { name: exported, declared_as, .. } if exported == head => {
711	                Some(declared_as.as_deref().unwrap_or(head))
712	            }
713	            LexedExport::LocalDeclaration { .. }
714	            | LexedExport::ReExportNamed { .. }
715	            | LexedExport::ReExportAll { .. }
716	            | LexedExport::ReExportNamespace { .. } => None,
717	        }) {
718	            let reference = rest.map_or_else(|| local.to_owned(), |rest| format!("{local}.{rest}"));
719	            if let Some(demand) = imported_demand(module, &data.imports, &reference) {
720	                let Ok(target) = self.resolve(module, &demand.specifier) else { return Ok(None) };
721	                return self.find_export_in(&target, &demand.name, visited, cut);
722	            }
723	        }
724	        if head == "default" {
725	            return Ok(None);
726	        }
727	        for export in &data.exports {
728	            if let LexedExport::ReExportAll { source_specifier, .. } = export {
729	                let Ok(target) = self.resolve(module, source_specifier) else { continue };
730	                if let Some(found) = self.find_export_in(&target, name, visited, cut)? {
731	                    return Ok(Some(found));
732	                }
733	            }
734	        }
735	        Ok(None)
736	    }
